:root {
  --clr-brand:        #1a1a2e;
  --clr-brand-mid:    #16213e;
  --clr-accent:       #e94560;
  --clr-accent-dark:  #c73652;
  --clr-accent-light: #ff6b81;
  --clr-bg:           #f8f8fc;
  --clr-surface:      #ffffff;
  --clr-border:       #e2e2ec;
  --clr-text:         #1a1a2e;
  --clr-text-muted:   #6b6b80;
  --clr-deal-bg:      #fff7ed;
  --clr-deal-badge:   #ea580c;

  --radius-sm:  6px;
  --radius-md: 12px;
  --radius-lg: 20px;

  --shadow-sm: 0 1px 3px rgba(0,0,0,.08), 0 1px 2px rgba(0,0,0,.06);
  --shadow-md: 0 4px 16px rgba(0,0,0,.10);
  --shadow-lg: 0 8px 32px rgba(0,0,0,.14);

  --font-sans: 'Inter', system-ui, -apple-system, sans-serif;

  --focus-ring: 0 0 0 3px rgba(233,69,96,.45);
  --transition: 200ms ease;
}

/* ─── Reset ─────────────────────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; }
body {
  font-family: var(--font-sans);
  background: var(--clr-bg);
  color: var(--clr-text);
  line-height: 1.6;
  overflow-x: hidden;
}
img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
ul, ol { list-style: none; }
button { cursor: pointer; font-family: inherit; }

/* ─── Focus ──────────────────────────────────────────────────────── */
:focus-visible {
  outline: 3px solid var(--clr-accent);
  outline-offset: 3px;
  border-radius: var(--radius-sm);
}

/* ─── Skip Link ──────────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  padding: .5rem 1rem;
  background: var(--clr-accent);
  color: #fff;
  font-weight: 700;
  border-radius: 0 0 var(--radius-sm) var(--radius-sm);
  z-index: 9999;
  transition: top var(--transition);
}
.skip-link:focus { top: 0; }

/* ─── Announcement bar ───────────────────────────────────────────── */
.announcement-bar {
  background: var(--clr-brand);
  color: #fff;
  text-align: center;
  padding: .5rem 1rem;
  font-size: .8125rem;
  letter-spacing: .02em;
}
.announcement-bar a { color: var(--clr-accent-light); text-decoration: underline; }

/* ─── Header ─────────────────────────────────────────────────────── */
.site-header {
  position: sticky;
  top: 0;
  z-index: 200;
  background: var(--clr-surface);
  border-bottom: 1px solid var(--clr-border);
  box-shadow: var(--shadow-sm);
}
.header-inner {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 1.5rem;
  display: flex;
  align-items: center;
  gap: 1.5rem;
  height: 64px;
}

/* Logo */
.site-logo {
  display: flex;
  align-items: center;
  gap: .5rem;
  font-size: 1.25rem;
  font-weight: 800;
  color: var(--clr-brand);
  white-space: nowrap;
  flex-shrink: 0;
}
.logo-mark {
  width: 32px; height: 32px;
  background: var(--clr-accent);
  border-radius: var(--radius-sm);
  display: grid;
  place-items: center;
  color: #fff;
  font-size: .9rem;
}

/* Primary nav */
.primary-nav { flex: 1; }
.primary-nav ul {
  display: flex;
  gap: .25rem;
}
.primary-nav a {
  padding: .4rem .75rem;
  border-radius: var(--radius-sm);
  font-size: .9375rem;
  font-weight: 500;
  color: var(--clr-text-muted);
  transition: color var(--transition), background var(--transition);
}
.primary-nav a:hover,
.primary-nav a[aria-current="page"] {
  color: var(--clr-text);
  background: var(--clr-bg);
}
.primary-nav a[aria-current="page"] { color: var(--clr-accent); font-weight: 600; }

/* Header actions */
.header-actions {
  display: flex;
  align-items: center;
  gap: .5rem;
  flex-shrink: 0;
}
.icon-btn {
  position: relative;
  width: 40px; height: 40px;
  display: grid;
  place-items: center;
  background: transparent;
  border: none;
  border-radius: var(--radius-sm);
  color: var(--clr-text);
  transition: background var(--transition), color var(--transition);
}
.icon-btn:hover { background: var(--clr-bg); color: var(--clr-accent); }
.icon-btn svg { width: 20px; height: 20px; }
.badge {
  position: absolute;
  top: 4px; right: 4px;
  min-width: 16px; height: 16px;
  background: var(--clr-accent);
  color: #fff;
  font-size: .625rem;
  font-weight: 700;
  border-radius: 9999px;
  display: grid;
  place-items: center;
  padding: 0 4px;
  line-height: 1;
}

/* Search form */
.header-search {
  flex: 1;
  max-width: 380px;
  position: relative;
}
.header-search input {
  width: 100%;
  padding: .5rem 2.5rem .5rem .875rem;
  border: 1.5px solid var(--clr-border);
  border-radius: 9999px;
  font-size: .875rem;
  background: var(--clr-bg);
  color: var(--clr-text);
  transition: border-color var(--transition);
}
.header-search input:focus { outline: none; border-color: var(--clr-accent); }
.header-search input::placeholder { color: var(--clr-text-muted); }
.search-submit {
  position: absolute;
  right: .5rem; top: 50%;
  transform: translateY(-50%);
  background: none;
  border: none;
  color: var(--clr-text-muted);
  padding: 0;
  display: grid;
  place-items: center;
}
.search-submit:hover { color: var(--clr-accent); }
.search-submit svg { width: 16px; height: 16px; }

/* Mobile menu toggle */
.mobile-menu-toggle {
  display: none;
  background: none;
  border: none;
  padding: .25rem;
  color: var(--clr-text);
}
.mobile-menu-toggle svg { width: 24px; height: 24px; }

/* ─── Mobile nav drawer ──────────────────────────────────────────── */
.mobile-nav {
  display: none;
  flex-direction: column;
  background: var(--clr-surface);
  border-top: 1px solid var(--clr-border);
  padding: 1rem 1.5rem;
  gap: .25rem;
}
.mobile-nav.open { display: flex; }
.mobile-nav a {
  padding: .625rem .5rem;
  border-radius: var(--radius-sm);
  font-size: 1rem;
  font-weight: 500;
  color: var(--clr-text-muted);
  border-bottom: 1px solid var(--clr-border);
}
.mobile-nav a:last-child { border-bottom: none; }
.mobile-nav a:hover { color: var(--clr-accent); background: var(--clr-bg); }

/* ─── Section shell ──────────────────────────────────────────────── */
.section { padding: 4rem 1.5rem; }
.section-inner { max-width: 1280px; margin: 0 auto; }

.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 2rem;
  flex-wrap: wrap;
}
.section-tag {
  display: inline-block;
  font-size: .75rem;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--clr-accent);
  margin-bottom: .375rem;
}
.section-title {
  font-size: clamp(1.375rem, 3vw, 1.875rem);
  font-weight: 800;
  line-height: 1.2;
  color: var(--clr-text);
}
.section-subtitle {
  font-size: .9375rem;
  color: var(--clr-text-muted);
  margin-top: .375rem;
}
.section-link {
  font-size: .875rem;
  font-weight: 600;
  color: var(--clr-accent);
  white-space: nowrap;
  display: flex;
  align-items: center;
  gap: .25rem;
  flex-shrink: 0;
}
.section-link:hover { color: var(--clr-accent-dark); }
.section-link::after { content: "→"; }

/* ─── Hero ───────────────────────────────────────────────────────── */
.hero {
  position: relative;
  overflow: hidden;
  background: linear-gradient(135deg, var(--clr-brand) 0%, #0f3460 100%);
  color: #fff;
  min-height: min(520px, 70vw);
  display: flex;
  align-items: center;
}
.hero-inner {
  max-width: 1280px;
  margin: 0 auto;
  padding: 4rem 1.5rem;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
  align-items: center;
  width: 100%;
}
.hero-eyebrow {
  font-size: .8125rem;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--clr-accent-light);
  margin-bottom: .75rem;
}
.hero-title {
  font-size: clamp(2rem, 5vw, 3.5rem);
  font-weight: 900;
  line-height: 1.1;
  margin-bottom: 1rem;
}
.hero-title span { color: var(--clr-accent-light); }
.hero-desc {
  font-size: clamp(.9375rem, 2vw, 1.125rem);
  color: rgba(255,255,255,.8);
  max-width: 48ch;
  margin-bottom: 2rem;
}
.hero-actions { display: flex; gap: 1rem; flex-wrap: wrap; }

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  padding: .75rem 1.5rem;
  border-radius: var(--radius-md);
  font-size: .9375rem;
  font-weight: 700;
  border: 2px solid transparent;
  transition: background var(--transition), color var(--transition),
              border-color var(--transition), transform var(--transition),
              box-shadow var(--transition);
}
.btn:active { transform: scale(.97); }
.btn-primary {
  background: var(--clr-accent);
  color: #fff;
  border-color: var(--clr-accent);
}
.btn-primary:hover { background: var(--clr-accent-dark); border-color: var(--clr-accent-dark); }
.btn-outline-light {
  background: transparent;
  color: #fff;
  border-color: rgba(255,255,255,.5);
}
.btn-outline-light:hover { background: rgba(255,255,255,.1); border-color: #fff; }
.btn-outline {
  background: transparent;
  color: var(--clr-accent);
  border-color: var(--clr-accent);
}
.btn-outline:hover { background: var(--clr-accent); color: #fff; }
.btn-sm { padding: .5rem 1rem; font-size: .8125rem; border-radius: var(--radius-sm); }

/* Hero visual */
.hero-visual {
  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;
}
.hero-badge {
  position: absolute;
  top: -1rem;
  right: 0;
  background: var(--clr-accent);
  color: #fff;
  font-size: .75rem;
  font-weight: 800;
  padding: .5rem .75rem;
  border-radius: var(--radius-md);
  text-align: center;
  line-height: 1.3;
  box-shadow: var(--shadow-md);
}
.hero-badge strong { display: block; font-size: 1.25rem; }
.hero-product-img {
  width: 100%;
  max-width: 420px;
  aspect-ratio: 1;
  border-radius: var(--radius-lg);
  object-fit: cover;
  box-shadow: var(--shadow-lg);
  background: linear-gradient(135deg, #1e3a5f 0%, #0f3460 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 8rem;
}
.hero-stats {
  display: flex;
  gap: 2rem;
  margin-top: 2.5rem;
  padding-top: 2rem;
  border-top: 1px solid rgba(255,255,255,.15);
}
.stat-value {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--clr-accent-light);
}
.stat-label {
  font-size: .8125rem;
  color: rgba(255,255,255,.65);
}

/* ─── Category pills ─────────────────────────────────────────────── */
.categories { padding: 2rem 1.5rem 0; }
.category-list {
  max-width: 1280px;
  margin: 0 auto;
  display: flex;
  gap: .75rem;
  overflow-x: auto;
  padding-bottom: .5rem;
  scrollbar-width: none;
}
.category-list::-webkit-scrollbar { display: none; }
.category-pill {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  padding: .5rem 1.125rem;
  border-radius: 9999px;
  background: var(--clr-surface);
  border: 1.5px solid var(--clr-border);
  font-size: .875rem;
  font-weight: 600;
  white-space: nowrap;
  color: var(--clr-text-muted);
  transition: background var(--transition), color var(--transition),
              border-color var(--transition);
}
.category-pill:hover,
.category-pill[aria-pressed="true"] {
  background: var(--clr-accent);
  color: #fff;
  border-color: var(--clr-accent);
}
.category-pill .pill-icon { font-size: 1rem; }

/* ─── Product grid ───────────────────────────────────────────────── */
.product-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(240px, 100%), 1fr));
  gap: 1.5rem;
}

/* Product card */
.product-card {
  background: var(--clr-surface);
  border-radius: var(--radius-md);
  border: 1px solid var(--clr-border);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: box-shadow var(--transition), transform var(--transition);
}
.product-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}
.product-img-wrap {
  position: relative;
  aspect-ratio: 1;
  background: var(--clr-bg);
  overflow: hidden;
}
.product-img-wrap .product-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  font-size: 4rem;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: transform 300ms ease;
}
.product-card:hover .product-img { transform: scale(1.04); }
.product-badges {
  position: absolute;
  top: .75rem;
  left: .75rem;
  display: flex;
  flex-direction: column;
  gap: .375rem;
}
.badge-pill {
  display: inline-block;
  padding: .2rem .6rem;
  border-radius: 9999px;
  font-size: .6875rem;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: .05em;
}
.badge-new { background: var(--clr-brand); color: #fff; }
.badge-sale { background: var(--clr-accent); color: #fff; }
.badge-bestseller { background: #f59e0b; color: #1a1a2e; }

.product-wishlist {
  position: absolute;
  top: .625rem;
  right: .625rem;
  width: 32px; height: 32px;
  border-radius: 50%;
  background: rgba(255,255,255,.9);
  border: none;
  display: grid;
  place-items: center;
  color: var(--clr-text-muted);
  transition: color var(--transition), background var(--transition);
  backdrop-filter: blur(4px);
}
.product-wishlist:hover,
.product-wishlist[aria-pressed="true"] { color: var(--clr-accent); background: #fff; }
.product-wishlist svg { width: 16px; height: 16px; }

.product-info { padding: 1rem; flex: 1; display: flex; flex-direction: column; }
.product-brand {
  font-size: .75rem;
  font-weight: 600;
  letter-spacing: .06em;
  text-transform: uppercase;
  color: var(--clr-text-muted);
  margin-bottom: .25rem;
}
.product-name {
  font-size: .9375rem;
  font-weight: 700;
  line-height: 1.35;
  color: var(--clr-text);
  margin-bottom: .5rem;
}
.product-name a:hover { color: var(--clr-accent); }
.product-rating {
  display: flex;
  align-items: center;
  gap: .375rem;
  margin-bottom: .625rem;
}
.stars { color: #f59e0b; font-size: .875rem; letter-spacing: -.05em; }
.rating-count { font-size: .75rem; color: var(--clr-text-muted); }
.product-price {
  display: flex;
  align-items: baseline;
  gap: .5rem;
  margin-top: auto;
  margin-bottom: .875rem;
}
.price-current {
  font-size: 1.1875rem;
  font-weight: 800;
  color: var(--clr-text);
}
.price-original {
  font-size: .875rem;
  color: var(--clr-text-muted);
  text-decoration: line-through;
}
.price-saving {
  font-size: .75rem;
  font-weight: 700;
  color: var(--clr-deal-badge);
}
.product-card .btn { width: 100%; justify-content: center; }

/* ─── Deals section ──────────────────────────────────────────────── */
.deals-section { background: var(--clr-deal-bg); }
.deals-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  gap: 1.25rem;
}

/* Featured deal (large) */
.deal-card {
  background: var(--clr-surface);
  border-radius: var(--radius-md);
  border: 1px solid var(--clr-border);
  overflow: hidden;
  display: flex;
  flex-direction: column;
}
.deal-card--featured {
  grid-row: span 2;
  flex-direction: row;
}
.deal-card--featured .deal-img-wrap { flex: 0 0 50%; }
.deal-img-wrap {
  position: relative;
  background: linear-gradient(135deg, #e0f2fe 0%, #bae6fd 100%);
  min-height: 180px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 6rem;
  overflow: hidden;
}
.deal-card--featured .deal-img-wrap { font-size: 9rem; min-height: auto; }
.deal-timer {
  position: absolute;
  bottom: .75rem;
  left: .75rem;
  right: .75rem;
  background: rgba(26,26,46,.85);
  backdrop-filter: blur(6px);
  color: #fff;
  border-radius: var(--radius-sm);
  padding: .5rem .75rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: .75rem;
}
.timer-label { font-weight: 600; opacity: .8; }
.timer-digits {
  display: flex;
  gap: .25rem;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
}
.timer-unit {
  background: rgba(255,255,255,.15);
  border-radius: 4px;
  padding: .15rem .35rem;
  min-width: 2rem;
  text-align: center;
  font-size: .8125rem;
}
.timer-sep { opacity: .6; align-self: flex-start; padding-top: .05rem; }
.deal-body {
  padding: 1.25rem;
  flex: 1;
  display: flex;
  flex-direction: column;
}
.deal-badge {
  display: inline-block;
  background: var(--clr-deal-badge);
  color: #fff;
  font-size: .6875rem;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: .06em;
  padding: .2rem .6rem;
  border-radius: 9999px;
  margin-bottom: .75rem;
  width: fit-content;
}
.deal-name {
  font-size: 1.0625rem;
  font-weight: 700;
  line-height: 1.3;
  margin-bottom: .5rem;
  color: var(--clr-text);
}
.deal-card--featured .deal-name { font-size: 1.375rem; }
.deal-desc {
  font-size: .875rem;
  color: var(--clr-text-muted);
  margin-bottom: 1rem;
  flex: 1;
}
.deal-price { margin-bottom: 1rem; }
.deal-price .price-current { font-size: 1.375rem; }
.deal-stock {
  margin-bottom: 1rem;
}
.stock-bar-wrap {
  height: 4px;
  background: var(--clr-border);
  border-radius: 9999px;
  overflow: hidden;
  margin-top: .375rem;
}
.stock-bar {
  height: 100%;
  background: var(--clr-accent);
  border-radius: 9999px;
  transition: width 800ms ease;
}
.stock-label {
  font-size: .75rem;
  color: var(--clr-text-muted);
}
.stock-label strong { color: var(--clr-deal-badge); }

/* ─── Editorial / Stories ────────────────────────────────────────── */
.editorial-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1.5rem;
}
.editorial-card {
  border-radius: var(--radius-md);
  overflow: hidden;
  background: var(--clr-surface);
  border: 1px solid var(--clr-border);
  display: grid;
  grid-template-columns: 1fr 1fr;
  transition: box-shadow var(--transition);
}
.editorial-card:hover { box-shadow: var(--shadow-md); }
.editorial-card--wide { grid-column: span 2; grid-template-columns: 1fr 1.2fr; }
.editorial-img {
  aspect-ratio: 4/3;
  object-fit: cover;
  font-size: 5rem;
  display: flex;
  align-items: center;
  justify-content: center;
}
.editorial-img--tall { aspect-ratio: auto; min-height: 260px; }
.editorial-img--forest { background: linear-gradient(135deg, #064e3b 0%, #065f46 60%, #047857 100%); }
.editorial-img--urban  { background: linear-gradient(135deg, #1e1b4b 0%, #312e81 60%, #4338ca 100%); }
.editorial-img--beach  { background: linear-gradient(135deg, #0c4a6e 0%, #0369a1 50%, #38bdf8 100%); }

.editorial-body {
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  justify-content: center;
}
.editorial-tag {
  font-size: .6875rem;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--clr-accent);
  margin-bottom: .5rem;
}
.editorial-title {
  font-size: 1.125rem;
  font-weight: 800;
  line-height: 1.3;
  margin-bottom: .625rem;
  color: var(--clr-text);
}
.editorial-card--wide .editorial-title { font-size: 1.375rem; }
.editorial-excerpt {
  font-size: .875rem;
  color: var(--clr-text-muted);
  line-height: 1.6;
  margin-bottom: 1.25rem;
  flex: 1;
}
.editorial-meta {
  display: flex;
  align-items: center;
  gap: .75rem;
  font-size: .8125rem;
  color: var(--clr-text-muted);
}
.editorial-meta .divider::before { content: "·"; }

/* ─── Brand strip ────────────────────────────────────────────────── */
.brands-section {
  background: var(--clr-surface);
  border-top: 1px solid var(--clr-border);
  border-bottom: 1px solid var(--clr-border);
  padding: 2rem 1.5rem;
}
.brands-inner {
  max-width: 1280px;
  margin: 0 auto;
}
.brands-label {
  text-align: center;
  font-size: .75rem;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--clr-text-muted);
  margin-bottom: 1.5rem;
}
.brands-list {
  display: flex;
  justify-content: center;
  align-items: center;
  flex-wrap: wrap;
  gap: 2rem 3rem;
}
.brand-name {
  font-size: 1rem;
  font-weight: 800;
  color: var(--clr-border);
  letter-spacing: .04em;
  transition: color var(--transition);
  text-transform: uppercase;
}
.brand-name:hover { color: var(--clr-text-muted); }

/* ─── Newsletter ─────────────────────────────────────────────────── */
.newsletter-section {
  background: linear-gradient(135deg, var(--clr-brand) 0%, #0f3460 100%);
  color: #fff;
  padding: 4rem 1.5rem;
  text-align: center;
}
.newsletter-inner { max-width: 560px; margin: 0 auto; }
.newsletter-icon { font-size: 3rem; margin-bottom: 1rem; }
.newsletter-title { font-size: clamp(1.5rem, 4vw, 2.25rem); font-weight: 900; margin-bottom: .75rem; }
.newsletter-desc { color: rgba(255,255,255,.75); margin-bottom: 2rem; font-size: 1rem; }
.newsletter-form { display: flex; gap: .75rem; }
.newsletter-form label { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0,0,0,0); }
.newsletter-input {
  flex: 1;
  padding: .75rem 1.125rem;
  border-radius: var(--radius-md);
  border: 2px solid rgba(255,255,255,.25);
  background: rgba(255,255,255,.1);
  color: #fff;
  font-size: .9375rem;
  transition: border-color var(--transition);
}
.newsletter-input::placeholder { color: rgba(255,255,255,.5); }
.newsletter-input:focus { outline: none; border-color: var(--clr-accent-light); }
.newsletter-privacy {
  font-size: .75rem;
  color: rgba(255,255,255,.5);
  margin-top: 1rem;
}

/* ─── Live region ────────────────────────────────────────────────── */
.live-region {
  position: absolute;
  width: 1px; height: 1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
}

/* ─── Footer ─────────────────────────────────────────────────────── */
.site-footer {
  background: var(--clr-brand);
  color: rgba(255,255,255,.75);
  padding: 3.5rem 1.5rem 2rem;
}
.footer-inner {
  max-width: 1280px;
  margin: 0 auto;
}
.footer-top {
  display: grid;
  grid-template-columns: 1.5fr 1fr 1fr 1fr;
  gap: 2.5rem;
  padding-bottom: 2.5rem;
  border-bottom: 1px solid rgba(255,255,255,.1);
  margin-bottom: 2rem;
}
.footer-brand .site-logo { color: #fff; margin-bottom: 1rem; }
.footer-brand p { font-size: .875rem; line-height: 1.7; }
.footer-social {
  display: flex;
  gap: .5rem;
  margin-top: 1.25rem;
}
.social-link {
  width: 36px; height: 36px;
  border-radius: var(--radius-sm);
  border: 1px solid rgba(255,255,255,.2);
  display: grid;
  place-items: center;
  color: rgba(255,255,255,.7);
  font-size: .875rem;
  transition: background var(--transition), color var(--transition);
}
.social-link:hover { background: var(--clr-accent); color: #fff; border-color: var(--clr-accent); }
.footer-col-title {
  font-size: .875rem;
  font-weight: 700;
  color: #fff;
  text-transform: uppercase;
  letter-spacing: .06em;
  margin-bottom: 1rem;
}
.footer-links { display: flex; flex-direction: column; gap: .5rem; }
.footer-links a {
  font-size: .875rem;
  color: rgba(255,255,255,.6);
  transition: color var(--transition);
}
.footer-links a:hover { color: #fff; }
.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 1rem;
  font-size: .8125rem;
  color: rgba(255,255,255,.45);
}
.footer-legal { display: flex; gap: 1.25rem; }
.footer-legal a { color: rgba(255,255,255,.45); }
.footer-legal a:hover { color: rgba(255,255,255,.8); }

/* ─── Cart drawer ────────────────────────────────────────────────── */
.cart-overlay {
  display: none;
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,.5);
  z-index: 300;
  backdrop-filter: blur(2px);
}
.cart-overlay.open { display: block; }
.cart-drawer {
  position: fixed;
  top: 0; right: 0; bottom: 0;
  width: min(420px, 100vw);
  background: var(--clr-surface);
  z-index: 301;
  display: flex;
  flex-direction: column;
  transform: translateX(100%);
  transition: transform 300ms cubic-bezier(.4,0,.2,1);
}
.cart-drawer.open { transform: translateX(0); }
.cart-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.25rem 1.5rem;
  border-bottom: 1px solid var(--clr-border);
}
.cart-title { font-size: 1.125rem; font-weight: 800; }
.cart-close {
  width: 36px; height: 36px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--clr-border);
  background: none;
  display: grid;
  place-items: center;
  color: var(--clr-text-muted);
}
.cart-close:hover { color: var(--clr-text); background: var(--clr-bg); }
.cart-close svg { width: 16px; height: 16px; }
.cart-body {
  flex: 1;
  overflow-y: auto;
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}
.cart-empty {
  text-align: center;
  padding: 3rem 0;
  color: var(--clr-text-muted);
}
.cart-empty p { font-size: .9375rem; margin-top: .5rem; }
.cart-item {
  display: flex;
  gap: 1rem;
  padding: 1rem;
  background: var(--clr-bg);
  border-radius: var(--radius-sm);
}
.cart-item-img {
  width: 64px; height: 64px;
  border-radius: var(--radius-sm);
  background: var(--clr-border);
  font-size: 2rem;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.cart-item-info { flex: 1; }
.cart-item-name { font-size: .9375rem; font-weight: 600; margin-bottom: .25rem; }
.cart-item-price { font-size: .875rem; color: var(--clr-text-muted); }
.cart-item-remove {
  background: none;
  border: none;
  color: var(--clr-text-muted);
  padding: .25rem;
  align-self: flex-start;
}
.cart-item-remove:hover { color: var(--clr-accent); }
.cart-item-remove svg { width: 14px; height: 14px; }
.cart-footer {
  padding: 1.5rem;
  border-top: 1px solid var(--clr-border);
}
.cart-subtotal {
  display: flex;
  justify-content: space-between;
  font-size: 1rem;
  font-weight: 700;
  margin-bottom: 1rem;
}
.cart-footer .btn { width: 100%; justify-content: center; }

/* ─── Toast ──────────────────────────────────────────────────────── */
.toast-container {
  position: fixed;
  bottom: 1.5rem;
  right: 1.5rem;
  z-index: 500;
  display: flex;
  flex-direction: column;
  gap: .75rem;
  pointer-events: none;
}
.toast {
  display: flex;
  align-items: center;
  gap: .75rem;
  padding: .875rem 1.25rem;
  background: var(--clr-brand);
  color: #fff;
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg);
  font-size: .875rem;
  font-weight: 500;
  pointer-events: auto;
  animation: slide-in-right 250ms ease forwards;
  max-width: 320px;
}
.toast.fade-out { animation: fade-out 300ms ease forwards; }
.toast-icon { font-size: 1.125rem; flex-shrink: 0; }
@keyframes slide-in-right {
  from { opacity: 0; transform: translateX(2rem); }
  to   { opacity: 1; transform: translateX(0); }
}
