const state = {
  cart: [],
  wishlist: new Set(),
};

/* ─── Utility ────────────────────────────────────────────────────── */
const $ = (sel, ctx = document) => ctx.querySelector(sel);
const $$ = (sel, ctx = document) => [...ctx.querySelectorAll(sel)];
const announce = (msg) => {
  const el = $('#live-region');
  if (!el) return;
  el.textContent = '';
  requestAnimationFrame(() => { el.textContent = msg; });
};

/* ─── Toast ──────────────────────────────────────────────────────── */
function showToast(message, icon = '✓') {
  const container = $('#toast-container');
  const toast = document.createElement('div');
  toast.className = 'toast';
  toast.setAttribute('role', 'status');
  toast.innerHTML = `<span class="toast-icon" aria-hidden="true">${icon}</span><span>${message}</span>`;
  container.appendChild(toast);
  setTimeout(() => {
    toast.classList.add('fade-out');
    toast.addEventListener('animationend', () => toast.remove(), { once: true });
  }, 3000);
}

/* ─── Cart ───────────────────────────────────────────────────────── */
function openCart() {
  const overlay = $('#cart-overlay');
  const drawer  = $('#cart-drawer');
  overlay.classList.add('open');
  drawer.classList.add('open');
  drawer.setAttribute('aria-hidden', 'false');
  overlay.setAttribute('aria-hidden', 'false');
  $('#cart-close').focus();
}

function closeCart() {
  const overlay = $('#cart-overlay');
  const drawer  = $('#cart-drawer');
  overlay.classList.remove('open');
  drawer.classList.remove('open');
  drawer.setAttribute('aria-hidden', 'true');
  overlay.setAttribute('aria-hidden', 'true');
  $('#cart-btn').focus();
}

function updateCartBadge() {
  const count = state.cart.reduce((sum, item) => sum + item.qty, 0);
  const badge = $('#cart-badge');
  badge.textContent = count;
  badge.hidden = count === 0;
  $('#cart-count-label').textContent = `Cart, ${count} item${count !== 1 ? 's' : ''}`;
}

function addToCart(product) {
  const existing = state.cart.find(i => i.id === product.id);
  if (existing) {
    existing.qty++;
  } else {
    state.cart.push({ ...product, qty: 1 });
  }
  updateCartBadge();
  renderCartItems();
  showToast(`Added "${product.name}" to cart`, '🛒');
  announce(`${product.name} added to cart. Cart now has ${state.cart.reduce((s,i) => s+i.qty,0)} items.`);
}

function removeFromCart(id) {
  const item = state.cart.find(i => i.id === id);
  state.cart = state.cart.filter(i => i.id !== id);
  updateCartBadge();
  renderCartItems();
  if (item) announce(`${item.name} removed from cart.`);
}

function renderCartItems() {
  const body = $('#cart-body');
  const footer = $('#cart-footer');
  if (state.cart.length === 0) {
    body.innerHTML = `
      <div class="cart-empty" role="status">
        <span aria-hidden="true" style="font-size:3rem">🛒</span>
        <p>Your cart is empty.</p>
      </div>`;
    footer.hidden = true;
    return;
  }
  footer.hidden = false;
  body.innerHTML = state.cart.map(item => `
    <div class="cart-item">
      <div class="cart-item-img" aria-hidden="true">${item.emoji}</div>
      <div class="cart-item-info">
        <div class="cart-item-name">${item.name}</div>
        <div class="cart-item-price">$${(item.price * item.qty).toFixed(2)} × ${item.qty}</div>
      </div>
      <button class="cart-item-remove" aria-label="Remove ${item.name} from cart" data-id="${item.id}">
        <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><line x1="12" y1="4" x2="4" y2="12"/><line x1="4" y1="4" x2="12" y2="12"/></svg>
      </button>
    </div>`).join('');

  const total = state.cart.reduce((s, i) => s + i.price * i.qty, 0);
  $('#cart-subtotal-amount').textContent = `$${total.toFixed(2)}`;

  $$('.cart-item-remove').forEach(btn => {
    btn.addEventListener('click', () => removeFromCart(btn.dataset.id));
  });
}

/* ─── Wishlist ───────────────────────────────────────────────────── */
function toggleWishlist(btn) {
  const id = btn.dataset.id;
  const name = btn.dataset.name;
  const pressed = btn.getAttribute('aria-pressed') === 'true';
  if (pressed) {
    state.wishlist.delete(id);
    btn.setAttribute('aria-pressed', 'false');
    btn.setAttribute('aria-label', `Add ${name} to wishlist`);
    announce(`${name} removed from wishlist.`);
  } else {
    state.wishlist.add(id);
    btn.setAttribute('aria-pressed', 'true');
    btn.setAttribute('aria-label', `Remove ${name} from wishlist`);
    showToast(`"${name}" saved to wishlist`, '♥');
    announce(`${name} added to wishlist.`);
  }
}

/* ─── Category filter ────────────────────────────────────────────── */
function initCategoryPills() {
  $$('.category-pill').forEach(pill => {
    pill.addEventListener('click', () => {
      $$('.category-pill').forEach(p => p.setAttribute('aria-pressed', 'false'));
      pill.setAttribute('aria-pressed', 'true');
      announce(`Showing ${pill.textContent.trim()} products.`);
    });
    pill.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); pill.click(); }
    });
  });
}

/* ─── Countdown timer ────────────────────────────────────────────── */
function initCountdown() {
  const deadline = new Date(Date.now() + 7 * 60 * 60 * 1000 + 23 * 60 * 1000 + 14 * 1000);
  const timers = $$('[data-countdown]');
  if (!timers.length) return;

  function tick() {
    const diff = Math.max(0, deadline - Date.now());
    const h = String(Math.floor(diff / 3600000)).padStart(2, '0');
    const m = String(Math.floor((diff % 3600000) / 60000)).padStart(2, '0');
    const s = String(Math.floor((diff % 60000) / 1000)).padStart(2, '0');
    timers.forEach(timer => {
      const hEl = timer.querySelector('[data-h]');
      const mEl = timer.querySelector('[data-m]');
      const sEl = timer.querySelector('[data-s]');
      if (hEl) hEl.textContent = h;
      if (mEl) mEl.textContent = m;
      if (sEl) sEl.textContent = s;
    });
  }
  tick();
  setInterval(tick, 1000);
}

/* ─── Mobile nav ─────────────────────────────────────────────────── */
function initMobileNav() {
  const toggle = $('#mobile-menu-toggle');
  const nav    = $('#mobile-nav');
  if (!toggle || !nav) return;

  toggle.addEventListener('click', () => {
    const open = nav.classList.toggle('open');
    toggle.setAttribute('aria-expanded', String(open));
    toggle.setAttribute('aria-label', open ? 'Close menu' : 'Open menu');
  });

  // Close on Escape
  nav.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
      nav.classList.remove('open');
      toggle.setAttribute('aria-expanded', 'false');
      toggle.focus();
    }
  });
}

/* ─── Newsletter ─────────────────────────────────────────────────── */
function initNewsletter() {
  const form  = $('#newsletter-form');
  const input = $('#newsletter-email');
  const msg   = $('#newsletter-msg');
  if (!form) return;

  form.addEventListener('submit', (e) => {
    e.preventDefault();
    const email = input.value.trim();
    if (!email) {
      input.setAttribute('aria-invalid', 'true');
      msg.textContent = 'Please enter your email address.';
      msg.style.color = 'var(--clr-accent-light)';
      input.focus();
      return;
    }
    input.setAttribute('aria-invalid', 'false');
    msg.textContent = '🎉 You\'re subscribed! Check your inbox for a welcome offer.';
    msg.style.color = '#86efac';
    input.value = '';
    announce('Subscription successful. Check your inbox for a welcome offer.');
  });
}

/* ─── Scroll-reveal ──────────────────────────────────────────────── */
function initScrollReveal() {
  if (!window.IntersectionObserver) return;
  const style = document.createElement('style');
  style.textContent = `
    .reveal { opacity: 0; transform: translateY(20px); transition: opacity 500ms ease, transform 500ms ease; }
    .reveal.visible { opacity: 1; transform: none; }
    @media (prefers-reduced-motion: reduce) { .reveal, .reveal.visible { opacity: 1 !important; transform: none !important; transition: none !important; } }
  `;
  document.head.appendChild(style);

  $$('.product-card, .deal-card, .editorial-card').forEach((el, i) => {
    el.classList.add('reveal');
    el.style.transitionDelay = `${(i % 4) * 60}ms`;
  });

  const io = new IntersectionObserver((entries) => {
    entries.forEach(en => {
      if (en.isIntersecting) { en.target.classList.add('visible'); io.unobserve(en.target); }
    });
  }, { threshold: 0.1 });

  $$('.reveal').forEach(el => io.observe(el));
}

/* ─── Init ───────────────────────────────────────────────────────── */
document.addEventListener('DOMContentLoaded', () => {
  /* Cart open/close */
  $('#cart-btn')?.addEventListener('click', openCart);
  $('#cart-close')?.addEventListener('click', closeCart);
  $('#cart-overlay')?.addEventListener('click', closeCart);
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && $('#cart-drawer')?.classList.contains('open')) closeCart();
  });

  /* Add-to-cart buttons */
  $$('"[data-add-to-cart]"');
  document.addEventListener('click', (e) => {
    const btn = e.target.closest('[data-add-to-cart]');
    if (!btn) return;
    addToCart({
      id:    btn.dataset.id,
      name:  btn.dataset.name,
      price: parseFloat(btn.dataset.price),
      emoji: btn.dataset.emoji,
    });
  });

  /* Wishlist buttons */
  document.addEventListener('click', (e) => {
    const btn = e.target.closest('.product-wishlist');
    if (!btn) return;
    toggleWishlist(btn);
  });

  initCategoryPills();
  initCountdown();
  initMobileNav();
  initNewsletter();
  initScrollReveal();
  updateCartBadge();
  renderCartItems();
});
